#pragma once
template<class Read> void corpusDetectionCheck(juce::AudioProcessor* p,juce::AudioBuffer<float>& audio,juce::MidiBuffer& midi,Read value,const std::string& path){
 auto check=[](bool x,const std::string& why){if(!x)throw std::runtime_error("Detection: "+why);};
 auto process=[&](){audio.clear();midi.clear();p->processBlock(audio,midi);};
 auto wait=[&](){for(int i=0;i<180000;++i){process();if(i%32==0)juce::MessageManager::getInstance()->runDispatchLoopUntil(1);if(i>100 && value("ready")>0 && value("pe_ready")>0 && value("pg_ready")>0 && value("pg_initializing")==0 && value("auto_settings_pending")==0 && value("rebuild_request")==0 && value("cg_stage")==0)return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Detection preparation timed out");};
 auto heap=[&](const char* key,int count){std::vector<double> v(count);check(za_native_gfx_heap_copy(p,key,v.data(),count)==count,"heap copy");return v;};
 check(p->getParameters().size()==250,"249 controls + oversampling");check(corpusGet(p,242)==1 && corpusGet(p,243)==.5 && corpusGet(p,244)==0,"default inference controls");
 juce::MemoryBlock oldState;p->getStateInformation(oldState);auto xml=juce::AudioProcessor::getXmlFromBinary(oldState.getData(),int(oldState.getSize()));check(bool(xml),"state XML");auto tree=juce::ValueTree::fromXml(*xml);for(int id=242;id<=244;++id){auto node=tree.getChildWithProperty("id","slider"+juce::String(id));if(node.isValid())tree.removeChild(node,nullptr);}auto oldXml=tree.createXml();juce::AudioProcessor::copyXmlToBinary(*oldXml,oldState);
 std::ofstream csv(path);csv<<"style,grains,min_ms,median_ms,p90_ms,max_ms,cached_span_matches\n";int counts[3]{};double medians[3]{};
 for(int mode: {1,0,2}){
  corpusSet(p,242,float(mode));wait();check(value("passage_mode")==mode && value("passage_run")==int(mode==2),"adopted inference mode");int n=int(value("grain_count"));auto g=heap("grain_base",n*64),xc=heap("xc_features",n*112);std::vector<double> durations;int matches=0;
  for(int i=0;i<n;++i){auto* z=g.data()+i*64;durations.push_back(z[3]/z[4]*1000);check(z[3]>0 && std::isfinite(z[6]) && std::isfinite(z[12]),"invalid grain");matches+=std::abs(xc[i*112+88]-z[2])<.1 && std::abs(xc[i*112+89]-z[3])<.1;}
  {std::ofstream dump(path+".mode"+std::to_string(mode)+".grains.csv");dump<<std::setprecision(17)<<"id,start_s,duration_s,motion_raw,motion,brightness_raw,brightness,cached_playback_start_s,cached_playback_duration_s\n";for(int i=0;i<n;++i){auto* z=g.data()+i*64;dump<<i<<','<<z[2]/z[4]<<','<<z[3]/z[4]<<','<<z[14]<<','<<z[19]<<','<<z[12]<<','<<z[17]<<','<<xc[i*112+88]/z[4]<<','<<xc[i*112+89]/z[4]<<'\n';}}
  if(mode!=1)check(matches==n,"playback cache extends or truncates detected unit");std::sort(durations.begin(),durations.end());counts[mode]=n;medians[mode]=durations[(n-1)/2];csv<<(mode==0?"Aggressive":mode==1?"Auto":"Coherent")<<','<<n<<','<<durations.front()<<','<<medians[mode]<<','<<durations[size_t(.9*(n-1))]<<','<<durations.back()<<','<<matches<<'\n';
  std::cout<<"DETECTION mode="<<mode<<" grains="<<n<<" median_ms="<<medians[mode]<<" max_ms="<<durations.back()<<" exact_cached_spans="<<matches<<'/'<<n<<std::endl;
 }
 check(counts[0]>counts[1] && medians[0]<medians[1],"Aggressive did not produce shorter units");check(medians[2]>medians[1],"Coherent did not preserve longer units");
 // Host recall and old projects. Restoring before a callback avoids building
 // intentionally transient edits, while testing normal parameter persistence.
 juce::MemoryBlock coherent;p->getStateInformation(coherent);corpusSet(p,242,0);corpusSet(p,243,.9f);corpusSet(p,244,2);p->setStateInformation(coherent.getData(),int(coherent.getSize()));wait();check(corpusGet(p,242)==2 && corpusGet(p,243)==.5 && corpusGet(p,244)==0,"host state round trip");
 for(auto [id,x]:std::vector<std::pair<int,float>>{{10,0},{25,8000},{76,0},{8,0},{56,0},{12,1},{11,12345},{45,0},{81,0}})corpusSet(p,id,x);process();
 std::vector<float> rendered;double peak=0;std::vector<double> times;
 for(int b=0;b<1800;++b){audio.clear();midi.clear();if(!b)midi.addEvent(juce::MidiMessage::noteOn(1,60,juce::uint8(100)),0);auto start=std::chrono::steady_clock::now();p->processBlock(audio,midi);if(value("voice_list_n")>0)times.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());for(int i=0;i<audio.getNumSamples();++i)for(int c=0;c<2;++c){float x=audio.getSample(c,i);check(std::isfinite(x),"nonfinite audio");peak=std::max(peak,std::abs(double(x)));rendered.push_back(x);}}
 int records=int(value("record_n"));check(records>0 && peak>1e-8 && value("record_done")>0,"completed audible plan");auto g=heap("grain_base",int(value("grain_count"))*64),r=heap("record_base",records*20);for(int i=0;i<records;++i){int id=int(r[i*20]);check(r[i*20+6]==g[id*64+2] && r[i*20+7]==g[id*64+3],"scheduled excerpt changed detected passage");}check(value("voice_list_n")==0,"event deadline did not end passage");
 corpusSet(p,65,0);corpusSet(p,243,.5f);int serial=(int(value("cmd_seen")/1048576)+1)%16;za_test_gfx_button(p,24,serial*1048576+4);double error=0;size_t at=0;
 for(int b=0;b<1802;++b){process();for(int i=0;i<audio.getNumSamples();++i)for(int c=0;c<2;++c){constexpr size_t delay=144*2;double expected=at<delay || at-delay>=rendered.size()?0:rendered[at-delay];error=std::max(error,std::abs(double(audio.getSample(c,i))-expected));++at;}}
 check(error<1e-6,"REPEAT changed passage waveform");std::sort(times.begin(),times.end());std::cout<<"DETECTION actual intact passage playback, event deadline and REPEAT error="<<error<<" peak="<<peak<<" p95_ms="<<times[size_t(.95*(times.size()-1))]<<" max_ms="<<times.back()<<std::endl;
 p->setStateInformation(oldState.getData(),int(oldState.getSize()));wait();check(corpusGet(p,242)==1 && corpusGet(p,243)==.5 && corpusGet(p,244)==0 && value("passage_run")==0,"older state did not restore original Auto");std::cout<<"DETECTION saved controls and old-state Auto defaults passed\n";
 uint32_t dsp=0,gfx=0;za_native_gfx_faults(p,&dsp,&gfx);check(!dsp&&!gfx&&value("invalid_audio")==0&&value("pe_read_errors")==0,"runtime faults");
}
template<class Read> void corpusDetectionCapture(juce::AudioProcessor* p,juce::AudioBuffer<float>& audio,juce::MidiBuffer& midi,Read value,const juce::File& folder){
 folder.createDirectory();corpusSet(p,55,4);std::unique_ptr<juce::AudioProcessorEditor> editor(p->createEditor());if(!editor)throw std::runtime_error("No detection editor");editor->setTopLeftPosition(-10000,-10000);editor->addToDesktop(juce::ComponentPeer::windowIsTemporary);editor->setVisible(true);editor->setSize(1180,920);
 auto find=[&](auto&& self,juce::Component& c)->juce::Component*{if(c.getName()=="Native JSFX graphics"||c.getName()=="EEL JSFX graphics")return &c;for(auto* child:c.getChildren())if(auto* r=self(self,*child))return r;return nullptr;};auto* view=find(find,*editor);if(!view)throw std::runtime_error("No detection canvas");
 auto frames=[&](int n=120){for(int i=0;i<n;++i){audio.clear();midi.clear();p->processBlock(audio,midi);juce::MessageManager::getInstance()->runDispatchLoopUntil(3);}};
 auto event=[&](juce::Point<float> point,bool down){auto local=view->getLocalPoint(editor.get(),point);auto now=juce::Time::getCurrentTime();return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),local,juce::ModifierKeys(down?juce::ModifierKeys::leftButtonModifier:0),1,0,0,0,0,view,view,now,local,now,1,false);};
 auto click=[&](juce::Point<float> point){view->mouseMove(event(point,false));view->mouseDown(event(point,true));frames(12);view->mouseUp(event(point,false));frames();};
 auto save=[&](const char* name){view->mouseMove(event({4,4},false));for(int i=0;i<12000;++i){frames(1);if(i>100 && value("cg_stage")==0 && value("auto_settings_pending")==0 && value("ready")>0 && value("pe_ready")>0 && value("pg_ready")>0)break;}frames();auto stream=folder.getChildFile(name).createOutputStream();if(!stream)throw std::runtime_error("Detection image");stream->setPosition(0);stream->truncate();juce::PNGImageFormat png;if(!png.writeImageToStream(editor->createComponentSnapshot(editor->getLocalBounds()),*stream))throw std::runtime_error("Detection PNG");};
 frames();save("Corpus-Detection-Auto.png");click({410,235});if(corpusGet(p,242)!=0)throw std::runtime_error("Header Aggressive click did not publish");save("Corpus-Detection-Aggressive.png");click({680,235});if(corpusGet(p,242)!=2)throw std::runtime_error("Header Coherent click did not publish");save("Corpus-Detection-Coherent.png");editor->setSize(1120,920);save("Corpus-Detection-Compact.png");
 p->editorBeingDeleted(editor.get());editor.reset();std::cout<<"DETECTION native header style clicks and large/compact UI captured\n";
}
